@namespace Lumeo

@* A nested group: its combinator cell, a card with its rows, a footer that adds a row to it and
   holds its drag handle and menu. The header, an empty card and the footer are drop zones. *@
@{
    var columns = Panel.ColumnsOf(Group, Index, CanMove);
    var description = Group.Combinator == FilterCombinator.And ? Context.Labels.GroupAll : Context.Labels.GroupAny;
    var issue = Panel.IssueFor(Group.Id);
    var isFirstRow = Depth == 1 && Index == 0;
}
<div role="group"
     aria-label="@string.Format(Context.Labels.RowLevel, description, Depth)"
     data-slot="filter-row"
     data-node-id="@Group.Id"
     data-parent-id="@ParentId"
     data-index="@Index"
     data-depth="@Depth"
     class="@Cx.Merge("flex flex-wrap items-center gap-1.5", FilterAdvancedRow.DropIndicatorClass, Class)"
     @attributes="AdditionalAttributes">
    <div class="@Cx.Join(FilterAdvancedRow.CombinatorBoxClass, "@max-[26rem]/track:w-full")">
        <FilterCombinatorCell NodeId="@Group.Id" ParentId="@ParentId" Index="Index" Combinator="Combinator" Active="@Panel.IsActive(Group.Id, FilterChipSegment.Combinator, columns, isFirstRow)" />
    </div>
    <div data-slot="filter-group"
         data-invalid="@(issue is not null ? "true" : null)"
         class="min-w-0 flex-1 rounded-md bg-muted/40 inset-ring inset-ring-border ps-2 pe-0 data-[invalid]:inset-ring-destructive/50 data-[drop-into]:bg-muted/60 data-[drop-into]:outline-1 data-[drop-into]:outline-solid data-[drop-into]:outline-border data-[drop-into]:-outline-offset-2">
        <div data-slot="filter-group-header" class="flex h-2 items-center" data-drop-parent="@Group.Id" data-drop-index="0" data-depth="@(Depth + 1)"></div>
        <div class="@Cx.Join("@container/track flex flex-col gap-3")">
            @if (Group.Rules.Count == 0)
            {
                <p data-slot="filter-group-empty" data-drop-parent="@Group.Id" data-drop-index="0" data-depth="@(Depth + 1)"
                   class="rounded-md border border-dashed px-2 py-3 text-center text-xs text-foreground/70 data-[drop-into]:border-primary/60 data-[drop-into]:bg-primary/5 data-[drop-into]:text-primary">
                    @Context.Labels.GroupPlaceholder
                </p>
            }
            else
            {
                @for (var i = 0; i < Group.Rules.Count; i++)
                {
                    var node = Group.Rules[i];
                    <FilterAdvancedNode @key="node.Id" Node="node" Index="i" ParentId="@Group.Id" Combinator="Group.Combinator" Depth="@(Depth + 1)" />
                }
            }
        </div>
        <div data-slot="filter-group-footer" class="flex flex-nowrap items-center gap-2 pb-2 pt-2 text-muted-foreground" data-drop-parent="@Group.Id" data-drop-index="@Group.Rules.Count" data-depth="@(Depth + 1)">
            <button type="button"
                    id="@Panel.CellId(Group.Id, FilterChipSegment.Add)"
                    data-filter-cell="add"
                    tabindex="@(Panel.IsActive(Group.Id, FilterChipSegment.Add, columns, isFirstRow) ? 0 : -1)"
                    class="@Cx.Join(AddClass, issue is not null ? "ring-1 ring-destructive/40" : null)"
                    aria-label="@Context.Labels.AddToGroup"
                    aria-invalid="@(issue is not null ? "true" : null)"
                    aria-description="@(issue is not null ? Context.Labels.IssueLabel(issue) : null)"
                    disabled="@Context.Disabled"
                    aria-disabled="@(Context.ReadOnly ? "true" : null)"
                    @onfocus="() => Context.SetFocus(Group.Id, FilterChipSegment.Add)"
                    @onkeydown="e => Panel.HandleCellKey(Group.Id, FilterChipSegment.Add, e, false)"
                    @onclick="() => Context.AddRow(Group.Id)">
                <SvgGlyph Svg="@(LumeoIcons.Plus)" class="h-4 w-4" />
                <span class="truncate">@Context.Labels.AddCondition</span>
            </button>
            <div class="ms-auto flex shrink-0 items-center gap-0.5 pe-1 text-muted-foreground">
                @if (CanMove)
                {
                    <FilterRowHandle NodeId="@Group.Id" Active="@Panel.IsActive(Group.Id, FilterChipSegment.Drag, columns, isFirstRow)" />
                }
                <DropdownMenu Open="_menuOpen" OpenChanged="v => { if (v && Context.Locked) return; _menuOpen = v; }">
                    <DropdownMenuTrigger AsChild Disabled="Context.Disabled">
                        <ChildContentSlot Context="slot">
                            <button type="button"
                                    id="@Panel.CellId(Group.Id, FilterChipSegment.Menu)"
                                    data-filter-cell="menu"
                                    tabindex="@(Panel.IsActive(Group.Id, FilterChipSegment.Menu, columns, isFirstRow) ? 0 : -1)"
                                    @attributes="slot.Attributes"
                                    @onclick="slot.OnClick"
                                    class="@FilterAdvancedRow.IconButtonClass(Context.Size)"
                                    aria-label="@Context.Labels.GroupMenu"
                                    disabled="@Context.Disabled"
                                    aria-disabled="@(Context.ReadOnly ? "true" : null)"
                                    @onfocus="() => Context.SetFocus(Group.Id, FilterChipSegment.Menu)"
                                    @onkeydown="e => Panel.HandleCellKey(Group.Id, FilterChipSegment.Menu, e, false)">
                                <SvgGlyph Svg="@(LumeoIcons.EllipsisVertical)" class="h-4 w-4" />
                            </button>
                        </ChildContentSlot>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent Align="Lumeo.Align.End" Class="@Cx.Merge(FilterStyles.MenuClass, Context.MenuClass)">
                        <DropdownMenuItem Disabled="Context.Locked" OnClick="() => Context.DuplicateNode(Group.Id)">
                            <SvgGlyph Svg="@(LumeoIcons.Copy)" class="h-4 w-4" />
                            <span class="min-w-0 truncate">@Context.Labels.Duplicate</span>
                        </DropdownMenuItem>
                        <DropdownMenuItem Disabled="Context.Locked" OnClick="() => Context.UnwrapGroup(Group.Id)">
                            <SvgGlyph Svg="@(LumeoIcons.Layers)" class="h-4 w-4" />
                            <span class="min-w-0 truncate">@Context.Labels.Ungroup</span>
                        </DropdownMenuItem>
                        <FilterMoveToMenuItems NodeId="@Group.Id" />
                        <DropdownMenuSeparator />
                        <DropdownMenuItem Variant="MenuItemVariant.Destructive" Disabled="Context.Locked" OnClick="() => Context.RemoveNode(Group.Id)">
                            <SvgGlyph Svg="@(LumeoIcons.Trash2)" class="h-4 w-4" />
                            <span class="min-w-0 truncate">@Context.Labels.RemoveGroup</span>
                        </DropdownMenuItem>
                    </DropdownMenuContent>
                </DropdownMenu>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter] public FiltersContext Context { get; set; } = default!;
    [CascadingParameter] public FiltersAdvancedPanel Panel { get; set; } = default!;
    [Parameter, EditorRequired] public FilterGroup Group { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public string ParentId { get; set; } = "";
    [Parameter] public FilterCombinator Combinator { get; set; }
    [Parameter] public int Depth { get; set; } = 1;
    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private bool _menuOpen;

    private bool CanMove => Context.Reorderable && (ParentId != Panel.Query.Id || Panel.Query.Rules.Count > 1);

    private string AddClass => Cx.Join(
        "inline-flex min-w-0 shrink items-center gap-2 overflow-hidden whitespace-nowrap rounded-md border border-input bg-background text-sm font-normal shadow-xs hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none",
        FilterStyles.ControlHeight(Context.Size), FilterStyles.PaddingX(Context.Size));
}

@namespace Lumeo

@* Dispatches a node to its row: a group card, a rule row, or the removable row of a rule whose
   field left the schema. *@
@if (Node is FilterGroup group)
{
    <FilterAdvancedGroup Group="group" Index="Index" ParentId="@ParentId" Combinator="Combinator" Depth="Depth" />
}
else if (Node is FilterRule rule)
{
    <FilterAdvancedRow Rule="rule" Index="Index" ParentId="@ParentId" Combinator="Combinator" Depth="Depth" />
}

@code {
    [Parameter, EditorRequired] public FilterNode Node { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public string ParentId { get; set; } = "";
    [Parameter] public FilterCombinator Combinator { get; set; }
    [Parameter] public int Depth { get; set; } = 1;
}

@namespace Lumeo
@implements IDisposable

@* One rule as a row of the advanced builder: combinator | field | condition | value | handle |
   menu. A text or number value edits in place; every other value opens its editor in a popover.
   A row added by the footer is pending until its field is picked and hides the rest until then. *@
@{
    var field = Context.Index.Get(Rule.Path);
    var columns = Panel.ColumnsOf(Rule, Index, CanMove);
    var isFirstRow = Depth == 1 && Index == 0;
}
@if (field is null)
{
    <div role="group"
         aria-label="@string.Format(Context.Labels.RowLevel, string.Join(Context.Labels.PathSeparator, Rule.Path), Depth)"
         data-slot="filter-row" data-node-id="@Rule.Id" data-parent-id="@ParentId" data-index="@Index" data-depth="@Depth" data-unknown="true"
         class="@Cx.Join("flex min-w-0 items-center gap-1.5", DropIndicatorClass)">
        <span class="min-w-0 flex-1 truncate text-sm text-muted-foreground">@string.Join(Context.Labels.PathSeparator, Rule.Path)</span>
        <div class="flex shrink-0 items-center gap-0.5 pe-1 text-muted-foreground">
            <button type="button" id="@Panel.CellId(Rule.Id, FilterChipSegment.Remove)" data-filter-cell="remove" tabindex="@(Panel.IsActive(Rule.Id, FilterChipSegment.Remove, columns, isFirstRow) ? 0 : -1)"
                    class="@IconButtonClass(Context.Size)" aria-label="@Context.Labels.Remove" disabled="@Context.Disabled" aria-disabled="@(Context.ReadOnly ? "true" : null)"
                    @onfocus="() => Context.SetFocus(Rule.Id, FilterChipSegment.Remove)" @onkeydown="e => Panel.HandleCellKey(Rule.Id, FilterChipSegment.Remove, e, false)" @onclick="() => Context.RemoveNode(Rule.Id)">
                <SvgGlyph Svg="@(LumeoIcons.X)" class="h-4 w-4" />
            </button>
        </div>
    </div>
}
else
{
    var operators = Context.ResolveOperators(field);
    var op = FilterOperators.Get(operators, Rule.Operator);
    var pending = Context.IsPending(Rule.Id);
    var takesValue = Rule.Operator.Length > 0 && FilterOperators.TakesValue(op);
    var inline = takesValue && FilterDisplay.UsesInlineEditor(Context, field, op);
    var issue = Panel.IssueFor(Rule.Id);
    var issueText = issue is null ? "" : Context.Labels.IssueLabel(issue);
    var pathText = Context.Index.FormatPath(Rule.Path, Context.Labels.PathSeparator);
    var operatorLabel = FilterDisplay.OperatorLabel(Context, Rule, op);
    var valueText = FilterDisplay.ValueText(Context, Rule, field, op);
    var valueFull = FilterDisplay.FullText(Context, Rule, field, op);
    var valueEmpty = FilterValues.IsBlank(Rule.Value);
    var f = field;
    <div role="group"
         aria-label="@string.Format(Context.Labels.RowLevel, $"{pathText} {operatorLabel}", Depth)"
         data-slot="filter-row"
         data-node-id="@Rule.Id"
         data-parent-id="@ParentId"
         data-index="@Index"
         data-depth="@Depth"
         data-pending="@(pending ? "true" : null)"
         class="@Cx.Join("group/row flex min-w-0 items-center gap-1.5", DropIndicatorClass)">
        <div class="@CombinatorBoxClass">
            <FilterCombinatorCell NodeId="@Rule.Id" ParentId="@ParentId" Index="Index" Combinator="Combinator" Active="@Panel.IsActive(Rule.Id, FilterChipSegment.Combinator, columns, isFirstRow)" />
        </div>
        <div class="flex min-w-0 flex-1 items-center gap-1.5">
            <div class="@Cx.Join(CellBoxClass, "lumeo-filter-cell-field")">
                <Popover Open="_pickerOpen" OpenChanged="OnPickerOpenChanged" Class="w-full">
                    <PopoverTrigger AsChild>
                        <ChildContentSlot Context="slot">
                            <button type="button"
                                    id="@Panel.CellId(Rule.Id, FilterChipSegment.Field)"
                                    data-filter-cell="field"
                                    tabindex="@(Panel.IsActive(Rule.Id, FilterChipSegment.Field, columns, isFirstRow) ? 0 : -1)"
                                    @attributes="slot.Attributes"
                                    @onclick="slot.OnClick"
                                    class="@CellClass"
                                    aria-label="@pathText"
                                    title="@pathText"
                                    disabled="@Context.Disabled"
                                    aria-disabled="@(Context.ReadOnly ? "true" : null)"
                                    @onfocus="() => Context.SetFocus(Rule.Id, FilterChipSegment.Field)"
                                    @onkeydown="e => Panel.HandleCellKey(Rule.Id, FilterChipSegment.Field, e, false)">
                                <span class="flex min-w-0 items-center gap-1.5 truncate">@f.Icon<span class="truncate">@pathText</span></span>
                                <SvgGlyph Svg="@(LumeoIcons.ChevronDown)" class="h-4 w-4 shrink-0" />
                            </button>
                        </ChildContentSlot>
                    </PopoverTrigger>
                    <PopoverContent Align="Lumeo.Align.Start" Class="w-auto min-w-56 p-0" FocusTargetId="@_pickerSearchId">
                        @if (_pickerOpen)
                        {
                            <FilterFieldPicker Path="_pickerPath" Query="@_pickerQuery" SearchId="@_pickerSearchId"
                                               OnPathChange="p => { _pickerPath = p; _pickerQuery = string.Empty; }"
                                               OnQueryChange="q => _pickerQuery = q"
                                               OnSelect="PickField" />
                        }
                    </PopoverContent>
                </Popover>
            </div>
            @if (!pending)
            {
                <div class="@Cx.Join(CellBoxClass, "lumeo-filter-cell-operator")">
                    <Popover Open="_operatorOpen" OpenChanged="OnOperatorOpenChanged" Class="w-full">
                        <PopoverTrigger AsChild>
                            <ChildContentSlot Context="slot">
                                <button type="button"
                                        id="@Panel.CellId(Rule.Id, FilterChipSegment.Operator)"
                                        data-filter-cell="operator"
                                        tabindex="@(Panel.IsActive(Rule.Id, FilterChipSegment.Operator, columns, isFirstRow) ? 0 : -1)"
                                        @attributes="slot.Attributes"
                                        @onclick="slot.OnClick"
                                        class="@Cx.Join(CellClass, "text-muted-foreground", Invalid(issue, FilterIssueColumn.Operator))"
                                        title="@operatorLabel"
                                        aria-invalid="@(issue?.Column == FilterIssueColumn.Operator ? "true" : null)"
                                        aria-description="@(issue?.Column == FilterIssueColumn.Operator ? issueText : null)"
                                        disabled="@Context.Disabled"
                                        aria-disabled="@(Context.ReadOnly ? "true" : null)"
                                        @onfocus="() => Context.SetFocus(Rule.Id, FilterChipSegment.Operator)"
                                        @onkeydown="e => Panel.HandleCellKey(Rule.Id, FilterChipSegment.Operator, e, false)">
                                    <span class="truncate">@operatorLabel</span>
                                    <SvgGlyph Svg="@(LumeoIcons.ChevronDown)" class="h-4 w-4 shrink-0" />
                                </button>
                            </ChildContentSlot>
                        </PopoverTrigger>
                        <PopoverContent Align="Lumeo.Align.Start" Class="w-auto min-w-40 p-0" FocusTargetId="@_operatorSearchId">
                            @if (_operatorOpen)
                            {
                                <FilterMenu Items="@FilterOperators.Visible(operators).Select(o => new FilterChoice(o.Value, o.Label)).ToList()"
                                            Selected="@(Rule.Operator.Length == 0 ? Array.Empty<string>() : new[] { Rule.Operator })"
                                            Searchable="false" AriaLabel="@f.Label" SearchPlaceholder="@Context.Labels.SearchOperators" MaxHeight="320"
                                            AutoFocusId="@_operatorSearchId" OnSelectionChange="v => OnOperatorPick(v, operators)" />
                            }
                        </PopoverContent>
                    </Popover>
                </div>
                <div class="@Cx.Join(CellBoxClass, "lumeo-filter-cell-value relative self-stretch")">
                    @if (takesValue && inline)
                    {
                        <Input id="@Panel.CellId(Rule.Id, FilterChipSegment.Value)"
                               data-filter-cell="value"
                               data-filter-cell-input="true"
                               tabindex="@(Panel.IsActive(Rule.Id, FilterChipSegment.Value, columns, isFirstRow) ? 0 : -1)"
                               type="@(f.Kind == FilterValueKind.Number ? "number" : "text")"
                               ShowStepButtons="false"
                               Value="@_inlineDraft"
                               OnInput="e => _inlineDraft = e.Value?.ToString() ?? string.Empty"
                               Placeholder="@(f.Placeholder ?? Context.Labels.ValuePlaceholder)"
                               Size="Context.Size"
                               Class="@Cx.Join("w-full", issueText.Length > 0 ? "pe-7" : null, Invalid(issue, FilterIssueColumn.Value))"
                               aria-label="@f.Label"
                               aria-invalid="@(issue?.Column == FilterIssueColumn.Value ? "true" : null)"
                               aria-description="@(issue?.Column == FilterIssueColumn.Value ? issueText : null)"
                               Disabled="Context.Disabled"
                               aria-disabled="@(Context.ReadOnly ? "true" : null)"
                               readonly="@(Context.ReadOnly ? "true" : null)"
                               @onfocus="() => Context.SetFocus(Rule.Id, FilterChipSegment.Value)"
                               @onblur="CommitInline"
                               @onkeydown="e => HandleInlineKey(e, f)" />
                        @if (issueText.Length > 0)
                        {
                            <span data-slot="filter-row-issue" aria-hidden="true" title="@issueText" class="pointer-events-none absolute end-2 top-1/2 flex -translate-y-1/2 items-center text-destructive [&_svg]:size-3.5">
                                <SvgGlyph Svg="@(LumeoIcons.CircleAlert)" />
                            </span>
                        }
                    }
                    else if (takesValue)
                    {
                        <Popover Open="_valueOpen" OpenChanged="OnValueOpenChanged" Class="w-full self-stretch">
                            <PopoverTrigger AsChild>
                                <ChildContentSlot Context="slot">
                                    <button type="button"
                                            id="@Panel.CellId(Rule.Id, FilterChipSegment.Value)"
                                            data-filter-cell="value"
                                            tabindex="@(Panel.IsActive(Rule.Id, FilterChipSegment.Value, columns, isFirstRow) ? 0 : -1)"
                                            @attributes="slot.Attributes"
                                            @onclick="slot.OnClick"
                                            class="@Cx.Join(CellClass, "h-full", valueEmpty ? "text-muted-foreground" : null, Invalid(issue, FilterIssueColumn.Value))"
                                            aria-label="@(Context.Locked ? valueFull : valueText)"
                                            title="@valueFull"
                                            aria-invalid="@(issue?.Column == FilterIssueColumn.Value ? "true" : null)"
                                            aria-description="@(issue?.Column == FilterIssueColumn.Value ? issueText : null)"
                                            disabled="@Context.Disabled"
                                            aria-disabled="@(Context.ReadOnly ? "true" : null)"
                                            @onfocus="() => Context.SetFocus(Rule.Id, FilterChipSegment.Value)"
                                            @onkeydown="e => Panel.HandleCellKey(Rule.Id, FilterChipSegment.Value, e, false)">
                                        <span class="min-w-0 flex-1 truncate text-start">
                                            @if ((Context.ValueTemplate ?? f.ValueTemplate) is { } template)
                                            {
                                                @template(FilterDisplay.ValueContext(Context, Rule, f, op))
                                            }
                                            else
                                            {
                                                @valueText
                                            }
                                        </span>
                                        @if (issueText.Length > 0)
                                        {
                                            <span data-slot="filter-row-issue" aria-hidden="true" title="@issueText" class="flex shrink-0 items-center text-destructive [&_svg]:size-3.5"><SvgGlyph Svg="@(LumeoIcons.CircleAlert)" /></span>
                                        }
                                    </button>
                                </ChildContentSlot>
                            </PopoverTrigger>
                            <PopoverContent Align="Lumeo.Align.Start" Class="w-auto p-0" FocusTargetId="@_editorFocusId">
                                @if (_valueOpen && op is not null && Context.ResolveEditor(f, op) is { } editor && _options is not null)
                                {
                                    @editor(EditorContext(f, op))
                                }
                            </PopoverContent>
                        </Popover>
                    }
                </div>
            }
        </div>
        <div class="flex shrink-0 items-center gap-0.5 pe-1 text-muted-foreground">
            @if (CanMove)
            {
                <FilterRowHandle NodeId="@Rule.Id" Active="@Panel.IsActive(Rule.Id, FilterChipSegment.Drag, columns, isFirstRow)" />
            }
            <DropdownMenu Open="_menuOpen" OpenChanged="v => { if (v && Context.Locked) return; _menuOpen = v; }">
                <DropdownMenuTrigger AsChild Disabled="Context.Disabled">
                    <ChildContentSlot Context="slot">
                        <button type="button"
                                id="@Panel.CellId(Rule.Id, FilterChipSegment.Menu)"
                                data-filter-cell="menu"
                                tabindex="@(Panel.IsActive(Rule.Id, FilterChipSegment.Menu, columns, isFirstRow) ? 0 : -1)"
                                @attributes="slot.Attributes"
                                @onclick="slot.OnClick"
                                class="@IconButtonClass(Context.Size)"
                                aria-label="@string.Format(Context.Labels.ChipMenu, f.Label)"
                                disabled="@Context.Disabled"
                                aria-disabled="@(Context.ReadOnly ? "true" : null)"
                                @onfocus="() => Context.SetFocus(Rule.Id, FilterChipSegment.Menu)"
                                @onkeydown="e => Panel.HandleCellKey(Rule.Id, FilterChipSegment.Menu, e, false)">
                            <SvgGlyph Svg="@(LumeoIcons.EllipsisVertical)" class="h-4 w-4" />
                        </button>
                    </ChildContentSlot>
                </DropdownMenuTrigger>
                <DropdownMenuContent Align="Lumeo.Align.End" Class="@Cx.Merge(FilterStyles.MenuClass, Context.MenuClass)">
                    <FilterRuleMenuItems RuleId="@Rule.Id" AllowGrouping="true" />
                </DropdownMenuContent>
            </DropdownMenu>
        </div>
    </div>
}

@code {
    [CascadingParameter] public FiltersContext Context { get; set; } = default!;
    [CascadingParameter] public FiltersAdvancedPanel Panel { get; set; } = default!;
    [Parameter, EditorRequired] public FilterRule Rule { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public string ParentId { get; set; } = "";
    [Parameter] public FilterCombinator Combinator { get; set; }
    [Parameter] public int Depth { get; set; } = 1;

    internal const string DropIndicatorClass = "relative rounded-md data-[dragging]:opacity-60 data-[drop-edge]:after:absolute data-[drop-edge]:after:start-0 data-[drop-edge]:after:end-1 data-[drop-edge]:after:z-10 data-[drop-edge]:after:h-0.5 data-[drop-edge]:after:bg-primary data-[drop-edge=before]:after:bottom-full data-[drop-edge=before]:after:mb-[5px] data-[drop-edge=after]:after:top-full data-[drop-edge=after]:after:mt-[5px]";
    internal const string CombinatorBoxClass = "@container/cell me-1.5 flex w-16 min-w-0 shrink-0 items-center justify-center";
    internal const string CellBoxClass = "@container/cell flex min-w-0 shrink grow-0";
    internal static string IconButtonClass(Lumeo.Size size) => Cx.Join(
        "inline-flex shrink-0 items-center justify-center rounded-md text-muted-foreground hover:inset-ring hover:inset-ring-border hover:text-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none data-[state=open]:inset-ring data-[state=open]:inset-ring-border",
        FilterStyles.ControlHeight(size), FilterStyles.IconWidth(size));

    private string CellClass => Cx.Join(
        "inline-flex w-full min-w-0 items-center justify-between gap-1.5 rounded-md border border-input bg-background text-sm font-normal shadow-xs [&>svg]:text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none @max-[7rem]/cell:gap-0 @max-[7rem]/cell:[&>svg]:hidden",
        FilterStyles.ControlHeight(Context.Size), FilterStyles.PaddingX(Context.Size));

    private static string? Invalid(FilterIssue? issue, FilterIssueColumn column) => issue?.Column == column ? "ring-1 ring-destructive/40" : null;

    private readonly string _pickerSearchId = FilterIds.New("filter-field");
    private readonly string _operatorSearchId = FilterIds.New("filter-op");
    private readonly string _editorFocusId = FilterIds.New("filter-value");
    private bool _pickerOpen, _operatorOpen, _valueOpen, _menuOpen;
    private IReadOnlyList<string> _pickerPath = Array.Empty<string>();
    private string _pickerQuery = "";
    private object? _valueDraft;
    private FilterOptionsState? _options;
    private string _inlineDraft = "";
    private string _inlineSeed = "";

    private bool CanMove => Context.Reorderable && (ParentId != Panel.Query.Id || Panel.Query.Rules.Count > 1);

    protected override void OnParametersSet()
    {
        var committed = Rule.Value switch
        {
            null => "",
            double d => d.ToString(System.Globalization.CultureInfo.InvariantCulture),
            IFormattable fm => fm.ToString(null, System.Globalization.CultureInfo.InvariantCulture) ?? "",
            _ => Rule.Value.ToString() ?? "",
        };
        if (committed != _inlineSeed) { _inlineSeed = committed; _inlineDraft = committed; }

        if (Context.FocusId == Rule.Id && Context.AutoOpen && Context.FocusSegment is { } segment && !Context.Locked)
        {
            switch (segment)
            {
                case FilterChipSegment.Field:
                    if (!_pickerOpen) { _pickerPath = Rule.Path.Take(Math.Max(0, Rule.Path.Count - 1)).ToList(); _pickerQuery = ""; _pickerOpen = true; }
                    break;
                case FilterChipSegment.Operator:
                    _operatorOpen = true;
                    break;
                case FilterChipSegment.Value:
                    if (Context.Index.Get(Rule.Path) is { } field && FilterDisplay.UsesInlineEditor(Context, field, FilterOperators.Get(Context.ResolveOperators(field), Rule.Operator)))
                        _ = Context.FocusElement(Panel.CellId(Rule.Id, FilterChipSegment.Value));
                    else if (!_valueOpen) OpenValue();
                    break;
            }
            Context.ConsumeAutoOpen(Rule.Id, segment);
        }
        if (Context.Index.Get(Rule.Path) is { ResolveValues: not null } rf) Context.EnsureResolved(rf, FilterValues.AsStrings(Rule.Value));
    }

    // ---- field ----
    private void OnPickerOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        if (open) { _pickerPath = Rule.Path.Take(Math.Max(0, Rule.Path.Count - 1)).ToList(); _pickerQuery = ""; }
        _pickerOpen = open;
        if (!open) Context.SetFocus(Rule.Id, FilterChipSegment.Field);
    }

    /// <summary>A picked field starts the row at its explicit default operator (if any) and moves on
    /// to the value, else opens the condition menu; the same field on a settled row only closes the
    /// picker. A pending row stays pending when the host vetoes the change.</summary>
    private void PickField(IReadOnlyList<string> path)
    {
        _pickerOpen = false;
        var wasPending = Context.IsPending(Rule.Id);
        if (Context.Index.Get(path) is not { } field) { Context.SetFocus(Rule.Id, FilterChipSegment.Field); return; }
        var explicitOperator = Context.ExplicitDefaultOperator(field);
        var same = path.SequenceEqual(Rule.Path);
        if (same && !wasPending) { Context.SetFocus(Rule.Id, FilterChipSegment.Field); return; }
        var op = explicitOperator ?? "";
        var changed = !same || Rule.Operator != op;
        if (changed && !Context.UpdateRule(Rule.Id, r => r with { Path = path, Operator = op, Value = null, Negated = false }))
        {
            Context.SetFocus(Rule.Id, FilterChipSegment.Field);
            return;
        }
        Context.ResolvePending(Rule.Id);
        var (segment, autoOpen) = Context.NextStepAfterField(field, explicitOperator);
        Context.SetFocus(Rule.Id, segment, autoOpen);
    }

    // ---- operator ----
    private void OnOperatorOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        _operatorOpen = open;
        if (!open) Context.SetFocus(Rule.Id, FilterChipSegment.Operator);
    }

    private void OnOperatorPick(IReadOnlyList<string> values, IReadOnlyList<FilterOperatorDef> operators)
    {
        var value = values.Count > 0 ? values[0] : null;
        _operatorOpen = false;
        if (value is null) { Context.SetFocus(Rule.Id, FilterChipSegment.Operator); return; }
        var chosen = FilterOperators.Get(operators, value);
        var current = FilterOperators.Get(operators, Rule.Operator);
        var building = Rule.Operator.Length == 0;
        Context.UpdateRule(Rule.Id, r => r with { Operator = value, Value = FilterValues.Coerce(r.Value, FilterOperators.ArityOf(current), FilterOperators.ArityOf(chosen)) });
        if (building && FilterOperators.TakesValue(chosen)) Context.SetFocus(Rule.Id, FilterChipSegment.Value, autoOpen: true);
        else Context.SetFocus(Rule.Id, FilterChipSegment.Operator);
    }

    // ---- inline value ----
    private void CommitInline()
    {
        if (_inlineDraft == _inlineSeed) return;
        var field = Context.Index.Get(Rule.Path);
        object? next;
        if (field?.Kind == FilterValueKind.Number)
        {
            var text = _inlineDraft.Trim();
            if (text.Length == 0) next = null;
            else if (double.TryParse(text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var d)) next = d;
            else { _inlineDraft = _inlineSeed; return; }
        }
        else next = _inlineDraft;
        Context.UpdateRule(Rule.Id, r => r with { Value = next });
    }

    private async Task HandleInlineKey(KeyboardEventArgs e, FilterField field)
    {
        if (e.Key == "Enter") { CommitInline(); return; }
        if (e.Key == "Escape") { _inlineDraft = _inlineSeed; return; }
        await Panel.HandleCellKey(Rule.Id, FilterChipSegment.Value, e, editing: true);
    }

    // ---- value popover ----
    private void OpenValue()
    {
        if (Context.Index.Get(Rule.Path) is not { } field) return;
        _valueDraft = Rule.Value;
        _options?.Dispose();
        _options = new FilterOptionsState(field, Context, enabled: true, () => _ = InvokeAsync(StateHasChanged));
        _valueOpen = true;
    }

    private void CloseValue()
    {
        _valueOpen = false;
        _options?.Dispose();
        _options = null;
        // Discard and an apply that changes nothing reach this from the editor's own click
        // handler, which re-renders the editor, not this component: without this the popover
        // stayed open on X.
        StateHasChanged();
        Context.SetFocus(Rule.Id, FilterChipSegment.Value);
    }

    private void OnValueOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        if (open) OpenValue(); else CloseValue();
    }

    private FilterEditorContext EditorContext(FilterField field, FilterOperatorDef op) => new(
        field, op, _valueDraft, FilterEditorHost.Amend, _options!, Context.Labels, Context.Size, _editorFocusId,
        setValue: v => _valueDraft = v,
        commit: (v, close) =>
        {
            Context.UpdateRule(Rule.Id, r => r with { Value = v });
            _valueDraft = v;
            if (close) CloseValue();
            return Task.CompletedTask;
        },
        cancel: CloseValue,
        back: CloseValue);

    public void Dispose() => _options?.Dispose();
}

@namespace Lumeo

<div data-slot="filter-editor" class="@Cx.Merge("w-40 min-w-0", Context.Field.Class, Class)" @attributes="AdditionalAttributes">
    <FilterMenu Items="Items"
                Selected="@(Context.Value is true ? new[] { "true" } : Context.Value is false ? new[] { "false" } : Array.Empty<string>())"
                OnSelectionChange="OnChange"
                AriaLabel="@Context.Field.Label"
                Searchable="false"
                AutoFocusId="@Context.AutoFocusId" />
</div>

@code {
    [Parameter, EditorRequired] public FilterEditorContext Context { get; set; } = default!;
    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private IReadOnlyList<FilterChoice> Items => new[] { new FilterChoice("true", Context.Labels.True), new FilterChoice("false", Context.Labels.False) };

    private async Task OnChange(IReadOnlyList<string> values)
    {
        // Pressing the chosen row again is a no-op, not a commit of false.
        if (values.Count == 0) return;
        var next = values[0] == "true";
        Context.SetValue(next);
        await Context.Commit(next);
    }
}

@namespace Lumeo
@implements IDisposable

@* One rule as a chip: field | operator | value | menu. The field segment only displays; the
   operator and value segments are popover triggers; the menu duplicates, negates or removes.
   Segments are fused by hand (rounded ends, overlapping borders) because each trigger sits in its
   own popover wrapper and a ButtonGroup only fuses direct children. *@
@if (Context.ChipTemplate is not null)
{
    @Context.ChipTemplate(Rule)
}
else if (Field is null)
{
    <div data-slot="filter-chip"
         data-unknown="true"
         id="@ElementId"
         role="group"
         aria-label="@string.Join(Context.Labels.PathSeparator, Rule.Path)"
         data-rule-id="@Rule.Id"
         data-index="@Index"
         tabindex="@(IsTabStop ? 0 : -1)"
         class="@ChipClass"
         @onfocusin="HandleFocusIn">
        <div data-slot="filter-segment" data-segment="field" class="@SegmentClass(first: true, last: false, interactive: false) text-muted-foreground">@string.Join(Context.Labels.PathSeparator, Rule.Path)</div>
        <button type="button" data-slot="filter-segment" data-segment="remove" class="@SegmentClass(first: false, last: true, interactive: true, icon: true)" aria-label="@Context.Labels.Remove" disabled="@Context.Disabled" aria-disabled="@(Context.ReadOnly ? "true" : null)" @onclick="() => Context.RemoveNode(Rule.Id)">
            <SvgGlyph Svg="@(LumeoIcons.X)" class="h-3.5 w-3.5" />
        </button>
    </div>
}
else
{
    var field = Field;
    var incomplete = Rule.Operator == "";
    var hasValue = !incomplete && FilterOperators.TakesValue(Operator);
    var display = Display;
    var issue = Context.IssueFor(Rule.Id);
    var showMenu = Context.HasMenuEntries(Rule.Id);
    var valueName = display.ValueEmpty && field.ValueText is null ? Context.Labels.NoValue : display.ValueText;
    var condition = $"{display.PathText} {display.OperatorLabel}{(hasValue ? " " + valueName : "")}".Trim() + (incomplete ? ", " + Context.Labels.Incomplete : "");
    <div data-slot="filter-chip"
         id="@ElementId"
         role="group"
         aria-label="@condition"
         data-focused="@(Focused ? "true" : null)"
         data-incomplete="@(incomplete ? "true" : null)"
         data-rule-id="@Rule.Id"
         data-index="@Index"
         tabindex="@(IsTabStop ? 0 : -1)"
         class="@ChipClass"
         @onfocusin="HandleFocusIn"
         @onfocus="() => _selfFocused = true"
         @onblur="() => _selfFocused = false"
         @onkeydown="HandleKeyDown">
        <Popover Open="_fieldOpen" OpenChanged="OnFieldOpenChanged">
            <PopoverTrigger AsChild>
                <ChildContentSlot Context="slot">
                    <button type="button"
                            data-slot="filter-segment"
                            data-segment="field"
                            id="@slot.Id"
                            @attributes="slot.Attributes"
                            @onclick="slot.OnClick"
                            @onpointerdown="() => Context.SetFocus(Rule.Id, FilterChipSegment.Field)"
                            class="@SegmentClass(first: true, last: false, interactive: true)"
                            title="@(display.PathCollapsed ? display.PathText : null)"
                            disabled="@Context.Disabled"
                            aria-disabled="@(Context.ReadOnly ? "true" : null)">
                        @field.Icon
                        <span class="flex items-center">@display.PathLabel</span>
                    </button>
                </ChildContentSlot>
            </PopoverTrigger>
            <PopoverContent Align="Lumeo.Align.Start" Class="w-auto min-w-56 p-0" FocusTargetId="@_fieldSearchId">
                @if (_fieldOpen)
                {
                    <FilterFieldPicker Path="_pickerPath" Query="@_pickerQuery" SearchId="@_fieldSearchId"
                                       OnPathChange="p => { _pickerPath = p; _pickerQuery = string.Empty; }"
                                       OnQueryChange="q => _pickerQuery = q"
                                       OnSelect="PickField" />
                }
            </PopoverContent>
        </Popover>

        <Popover Open="_operatorOpen" OpenChanged="OnOperatorOpenChanged">
            <PopoverTrigger AsChild>
                <ChildContentSlot Context="slot">
                    <button type="button"
                            data-slot="filter-segment"
                            data-segment="operator"
                            id="@slot.Id"
                            @attributes="slot.Attributes"
                            @onclick="slot.OnClick"
                            @onpointerdown="() => Context.SetFocus(Rule.Id, FilterChipSegment.Operator)"
                            class="@SegmentClass(first: false, last: !hasValue && !showMenu, interactive: true) @(incomplete ? "text-foreground" : "text-muted-foreground")"
                            disabled="@Context.Disabled"
                            aria-disabled="@(Context.ReadOnly ? "true" : null)">
                        @display.OperatorLabel
                    </button>
                </ChildContentSlot>
            </PopoverTrigger>
            <PopoverContent Align="Lumeo.Align.Start" Class="w-auto min-w-40 p-0" FocusTargetId="@_operatorSearchId">
                @if (_operatorOpen)
                {
                    <FilterMenu Items="OperatorChoices"
                                Selected="@(incomplete ? Array.Empty<string>() : new[] { Rule.Operator })"
                                Searchable="false"
                                AriaLabel="@field.Label"
                                SearchPlaceholder="@Context.Labels.SearchOperators"
                                MaxHeight="320"
                                AutoFocusId="@_operatorSearchId"
                                OnSelectionChange="OnOperatorPick" />
                }
            </PopoverContent>
        </Popover>

        @if (hasValue)
        {
            <Popover Open="_valueOpen" OpenChanged="OnValueOpenChanged">
                <PopoverTrigger AsChild>
                    <ChildContentSlot Context="slot">
                        <button type="button"
                                data-slot="filter-segment"
                                data-segment="value"
                                id="@slot.Id"
                                @attributes="slot.Attributes"
                                @onclick="slot.OnClick"
                                @onpointerdown="() => Context.SetFocus(Rule.Id, FilterChipSegment.Value)"
                                class="@SegmentClass(first: false, last: !showMenu, interactive: true) @(display.ValueEmpty ? "text-muted-foreground" : null) @(issue is not null ? "text-destructive" : null)"
                                aria-label="@(Context.Locked ? display.ValueFullText : display.ValueText)"
                                aria-invalid="@(issue is not null ? "true" : null)"
                                aria-description="@issue?.Message"
                                title="@(issue?.Message ?? (display.ValueFullText == display.ValueText ? null : display.ValueFullText))"
                                disabled="@Context.Disabled"
                                aria-disabled="@(Context.ReadOnly ? "true" : null)">
                            @display.ValueLabel
                        </button>
                    </ChildContentSlot>
                </PopoverTrigger>
                <PopoverContent Align="Lumeo.Align.Start" Class="w-auto p-0" FocusTargetId="@_editorFocusId">
                    @if (_valueOpen && Operator is { } op && Context.ResolveEditor(field, op) is { } editor && _options is not null)
                    {
                        @editor(EditorContext(field, op))
                    }
                </PopoverContent>
            </Popover>
        }

        @if (showMenu)
        {
            <DropdownMenu Open="_menuOpen" OpenChanged="OnMenuOpenChanged">
                <DropdownMenuTrigger AsChild Disabled="Context.Disabled">
                    <ChildContentSlot Context="slot">
                        <button type="button"
                                data-slot="filter-segment"
                                data-segment="menu"
                                id="@slot.Id"
                                @attributes="slot.Attributes"
                                @onclick="slot.OnClick"
                                @onpointerdown="() => Context.SetFocus(Rule.Id, FilterChipSegment.Menu)"
                                class="@SegmentClass(first: false, last: true, interactive: true, icon: true)"
                                aria-label="@string.Format(Context.Labels.ChipMenu, field.Label)"
                                disabled="@Context.Disabled"
                                aria-disabled="@(Context.ReadOnly ? "true" : null)">
                            <SvgGlyph Svg="@(LumeoIcons.EllipsisVertical)" class="h-3.5 w-3.5" />
                        </button>
                    </ChildContentSlot>
                </DropdownMenuTrigger>
                <DropdownMenuContent Align="Lumeo.Align.End" Class="@Cx.Merge(FilterStyles.MenuClass, Context.MenuClass)">
                    <FilterRuleMenuItems RuleId="@Rule.Id" AllowGrouping="@(Context.Variant == FiltersVariant.Advanced)" OnConvertToAdvanced="OnConvertToAdvanced" />
                </DropdownMenuContent>
            </DropdownMenu>
        }
    </div>
}

@code {
    [CascadingParameter] public FiltersContext Context { get; set; } = default!;
    [Parameter, EditorRequired] public FilterRule Rule { get; set; } = default!;
    /// <summary>The chip's position in the row, for the arrow keys.</summary>
    [Parameter] public int Index { get; set; }
    /// <summary>Whether this chip holds the row's focus record.</summary>
    [Parameter] public bool Focused { get; set; }
    /// <summary>Whether this chip is the row's tab stop (the focused one, else the first).</summary>
    [Parameter] public bool IsTabStop { get; set; }
    /// <summary>A segment asked to open on this render (after the field or operator step).</summary>
    [Parameter] public FilterChipSegment? AutoOpenSegment { get; set; }
    [Parameter] public EventCallback OnConvertToAdvanced { get; set; }

    private readonly string _operatorSearchId = FilterIds.New("filter-op");
    private readonly string _editorFocusId = FilterIds.New("filter-value");
    private readonly string _fieldSearchId = FilterIds.New("filter-field");
    private bool _fieldOpen;
    private IReadOnlyList<string> _pickerPath = Array.Empty<string>();
    private string _pickerQuery = "";
    private bool _operatorOpen;
    private bool _valueOpen;
    private bool _menuOpen;
    private bool _selfFocused;
    private object? _valueDraft;
    private FilterOptionsState? _options;

    private string ElementId => Context.ChipElementId(Rule.Id);

    private FilterField? Field => Context.Index.Get(Rule.Path);
    private IReadOnlyList<FilterOperatorDef> Operators => Field is null ? Array.Empty<FilterOperatorDef>() : Context.ResolveOperators(Field);
    private FilterOperatorDef? Operator => FilterOperators.Get(Operators, Rule.Operator);
    private IReadOnlyList<FilterChoice> OperatorChoices => FilterOperators.Visible(Operators).Select(o => new FilterChoice(o.Value, o.Label)).ToList();

    private string ChipClass => Cx.Merge("inline-flex items-stretch rounded-md focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-2");

    private string SegmentClass(bool first, bool last, bool interactive, bool icon = false) => Cx.Join(
        "inline-flex items-center gap-1.5 whitespace-nowrap border border-input bg-background text-sm select-none min-w-0",
        FilterStyles.ControlHeight(Context.Size),
        icon ? Cx.Join(FilterStyles.IconWidth(Context.Size), "justify-center px-0") : FilterStyles.PaddingX(Context.Size),
        first ? "rounded-s-md" : "-ms-px",
        last ? "rounded-e-md" : null,
        !first && !last ? "rounded-none" : null,
        interactive ? "relative cursor-default hover:bg-accent hover:text-accent-foreground focus-visible:z-10 focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none" : "cursor-default");

    protected override void OnParametersSet()
    {
        if (AutoOpenSegment is { } segment && !Context.Locked)
        {
            if (segment == FilterChipSegment.Operator && !_operatorOpen) _operatorOpen = true;
            else if (segment == FilterChipSegment.Value && !_valueOpen) OpenValue();
            else if (segment == FilterChipSegment.Field && !_fieldOpen) OpenField();
            Context.ConsumeAutoOpen(Rule.Id, segment);
        }
        if (Field is { } f && f.ResolveValues is not null) Context.EnsureResolved(f, FilterValues.AsStrings(Rule.Value));
        // a menu that lost its entries while open must not reopen by itself when they come back
        if (_menuOpen && !Context.HasMenuEntries(Rule.Id)) _menuOpen = false;
    }

    // ---- display ----
    private sealed record RuleDisplay(string PathText, RenderFragment PathLabel, bool PathCollapsed, string OperatorLabel, RenderFragment ValueLabel, string ValueText, string ValueFullText, bool ValueEmpty);

    private RuleDisplay Display
    {
        get
        {
            var fld = Field!;
            var labels = Context.Labels;
            var pathText = Context.Index.FormatPath(Rule.Path, labels.PathSeparator);
            var chain = Context.Index.Chain(Rule.Path);
            var collapsed = chain.Count > Context.MaxPathSegments && Context.MaxPathSegments >= 2;
            RenderFragment pathLabel = b =>
            {
                if (chain.Count == 0) { b.AddContent(0, pathText); return; }
                var shown = collapsed ? new[] { chain[0], null, chain[^1] } : chain.ToArray();
                var seq = 0;
                for (var i = 0; i < shown.Length; i++)
                {
                    if (i > 0)
                    {
                        b.OpenComponent<SvgGlyph>(seq++);
                        b.AddAttribute(seq++, "Svg", LumeoIcons.ChevronRight);
                        b.AddAttribute(seq++, "class", "mx-[3px] inline-block size-3 shrink-0 self-center text-muted-foreground");
                        b.AddAttribute(seq++, "aria-hidden", "true");
                        b.CloseComponent();
                    }
                    b.OpenElement(seq++, "span");
                    if (shown[i] is null) { b.AddAttribute(seq++, "class", "text-muted-foreground"); b.AddAttribute(seq++, "title", pathText); b.AddContent(seq++, "..."); }
                    else b.AddContent(seq++, shown[i]!.Label);
                    b.CloseElement();
                }
            };
            var op = Operator;
            var operatorLabel = op is not null ? (Rule.Negated ? string.Format(labels.Negated, op.Label) : op.Label) : (Rule.Operator.Length > 0 ? Rule.Operator : labels.SelectCondition);
            var values = Rule.Values;
            var valueEmpty = FilterValues.IsBlank(Rule.Value) || values.Count == 0;
            var optionBacked = fld.Kind is FilterValueKind.Select or FilterValueKind.MultiSelect || fld.HasOptions;
            var context = new FilterValueContext(Rule.Value, values, fld, op ?? new FilterOperatorDef(Rule.Operator, Rule.Operator), values.Select(v => v is null ? null : Context.ResolveOption(fld, v.ToString()!)).Where(o => o is not null).Select(o => o!).ToList(), labels);
            var valueText = fld.ValueText is not null ? fld.ValueText(context) : DefaultValueText(fld, op, optionBacked);
            var template = Context.ValueTemplate ?? fld.ValueTemplate;
            RenderFragment valueLabel = template is not null ? template(context) : (b =>
            {
                var single = values.Count == 1 && values[0] is not null ? values[0]!.ToString() : null;
                var icon = single is null ? null : Context.ResolveOption(fld, single)?.Icon;
                if (icon is null) { b.AddContent(0, valueText); return; }
                b.OpenElement(1, "span"); b.AddAttribute(2, "class", "flex items-center gap-1.5"); b.AddContent(3, icon); b.AddContent(4, valueText); b.CloseElement();
            });
            var fullText = fld.ValueText is not null || Rule.Value is not System.Collections.IEnumerable || Rule.Value is string || FilterOperators.ArityOf(op) == FilterArity.Range || values.Count < 2
                ? valueText
                : string.Format(labels.ValueDetail, valueText, string.Join(", ", values.Select(v => v is null ? "" : Context.ResolveOption(fld, v.ToString()!)?.Label ?? v.ToString())));
            return new RuleDisplay(pathText, pathLabel, collapsed, operatorLabel, valueLabel, valueText, fullText, valueEmpty);
        }
    }

    private string DefaultValueText(FilterField field, FilterOperatorDef? op, bool optionBacked)
    {
        var labels = Context.Labels;
        var value = Rule.Value;
        var emptyLabel = optionBacked ? labels.SelectPlaceholder : field.Placeholder ?? labels.ValuePlaceholder;
        if (FilterValues.IsBlank(value)) return emptyLabel;
        if (FilterOperators.ArityOf(op) == FilterArity.Range && value is FilterRange range)
            return string.Format(labels.ValueRange, One(field, range.From), One(field, range.To));
        if (value is not string && value is System.Collections.IEnumerable list)
        {
            var items = list.Cast<object?>().ToList();
            if (items.Count == 0) return emptyLabel;
            if (items.Count == 1) return One(field, items[0]);
            return string.Format(labels.ValueCount, items.Count);
        }
        return One(field, value);
    }

    private string One(FilterField field, object? value)
    {
        var labels = Context.Labels;
        switch (value)
        {
            case null: return "";
            case bool b: return b ? labels.True : labels.False;
            case FilterDateValue d: return FilterDates.Format(d, labels);
            case DateOnly d: return FilterDates.Format(FilterDateValue.Of(d), labels);
            case DateTime dt: return FilterDates.Format(FilterDateValue.Of(DateOnly.FromDateTime(dt)), labels);
            default:
                var text = value.ToString() ?? "";
                return Context.ResolveOption(field, text)?.Label ?? text;
        }
    }

    // ---- field ----
    private void OpenField()
    {
        _pickerPath = Array.Empty<string>();
        _pickerQuery = "";
        _fieldOpen = true;
    }

    private void OnFieldOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        if (open) OpenField(); else _fieldOpen = false;
        if (!open) Context.SetFocus(Rule.Id, FilterChipSegment.Field);
    }

    /// <summary>A new field starts the rule over at its default condition, with the operator menu
    /// open; the same field only closes the picker.</summary>
    private void PickField(IReadOnlyList<string> path)
    {
        _fieldOpen = false;
        if (path.SequenceEqual(Rule.Path)) { Context.SetFocus(Rule.Id, FilterChipSegment.Field); return; }
        if (Context.Index.Get(path) is not { } field) return;
        var explicitOperator = Context.ExplicitDefaultOperator(field);
        Context.UpdateRule(Rule.Id, r => r with { Path = path, Operator = explicitOperator ?? "", Value = null, Negated = false });
        var (segment, autoOpen) = Context.NextStepAfterField(field, explicitOperator);
        Context.SetFocus(Rule.Id, segment, autoOpen);
    }

    // ---- operator popover ----
    private void OnOperatorOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        _operatorOpen = open;
        if (!open) Context.SetFocus(Rule.Id, FilterChipSegment.Operator);
    }

    private void OnOperatorPick(IReadOnlyList<string> values)
    {
        var value = values.Count > 0 ? values[0] : null;
        if (value is null) { _operatorOpen = false; Context.SetFocus(Rule.Id, FilterChipSegment.Operator); return; }
        var chosen = FilterOperators.Get(Operators, value);
        var building = Rule.Operator == "";
        var current = Operator;
        Context.UpdateRule(Rule.Id, r => r with { Operator = value, Value = FilterValues.Coerce(r.Value, FilterOperators.ArityOf(current), FilterOperators.ArityOf(chosen)) });
        _operatorOpen = false;
        if (building && FilterOperators.TakesValue(chosen))
        {
            // The step after the condition is the value: open it once this popover has closed.
            Context.SetFocus(Rule.Id, FilterChipSegment.Value, autoOpen: true);
            return;
        }
        Context.SetFocus(Rule.Id, FilterChipSegment.Operator);
    }

    // ---- value popover ----
    private void OpenValue()
    {
        if (Field is null) return;
        _valueDraft = Rule.Value;
        _options?.Dispose();
        _options = new FilterOptionsState(Field, Context, enabled: true, () => _ = InvokeAsync(StateHasChanged));
        _valueOpen = true;
    }

    private void CloseValue()
    {
        _valueOpen = false;
        _options?.Dispose();
        _options = null;
        // Discard and an apply that changes nothing reach this from the editor's own click
        // handler, which re-renders the editor, not this component: without this the popover
        // stayed open on X.
        StateHasChanged();
        Context.SetFocus(Rule.Id, FilterChipSegment.Value);
    }

    private void OnValueOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        if (open) OpenValue(); else CloseValue();
    }

    private FilterEditorContext EditorContext(FilterField field, FilterOperatorDef op) => new(
        field, op, _valueDraft, FilterEditorHost.Amend, _options!, Context.Labels, Context.Size, _editorFocusId,
        setValue: v => _valueDraft = v,
        commit: (v, close) =>
        {
            Context.UpdateRule(Rule.Id, r => r with { Value = v });
            _valueDraft = v;
            if (close) CloseValue();
            return Task.CompletedTask;
        },
        cancel: CloseValue,
        back: CloseValue);

    // ---- menu ----
    private void OnMenuOpenChanged(bool open)
    {
        if (open && Context.Locked) return;
        _menuOpen = open;
    }

    // ---- focus and keys ----
    private void HandleFocusIn()
    {
        if (!Focused) Context.SetFocus(Rule.Id, null);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (!_selfFocused) return;
        var locked = Context.Locked;
        switch (e.Key)
        {
            case "ArrowRight" when e.AltKey:
            case "ArrowLeft" when e.AltKey:
                if (locked || !Context.Reorderable) return;
                Context.MoveNode(Rule.Id, e.Key == "ArrowRight" ? 1 : -1);
                return;
            case "ArrowRight": Context.Owner.FocusChipAt(Index + 1); return;
            case "ArrowLeft": Context.Owner.FocusChipAt(Index - 1); return;
            case "Home": Context.Owner.FocusChipAt(0); return;
            case "End": Context.Owner.FocusChipAt(int.MaxValue); return;
            case "Backspace":
            case "Delete":
                if (locked) return;
                Context.RemoveNode(Rule.Id);
                Context.Owner.FocusChipAt(Index);
                return;
            case "Enter":
            case " ":
                if (locked) return;
                var segment = Rule.Operator.Length > 0 && FilterOperators.TakesValue(Operator) ? FilterChipSegment.Value : FilterChipSegment.Operator;
                Context.SetFocus(Rule.Id, segment, autoOpen: true);
                await Task.CompletedTask;
                return;
        }
    }

    public void Dispose() => _options?.Dispose();
}

