@code {
    [Parameter, EditorRequired] public FilterEditorContext Context { get; set; } = default!;
    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string _text = "";
    private string _fromText = "";
    private string _toText = "";

    private bool IsRange => Context.Operator.Arity == FilterArity.Range;
    private FilterDateValue? Single => FilterDates.Coerce(Context.Value);
    private FilterRange Range => Context.Value as FilterRange ?? new FilterRange(null, null);
    private FilterDateValue? Bound(int i) => FilterDates.Coerce(i == 0 ? Range.From : Range.To);

    protected override void OnInitialized()
    {
        _text = Single is { } s ? FilterDates.Format(s, Context.Labels) : "";
        _fromText = Bound(0) is { } f ? FilterDates.Format(f, Context.Labels) : "";
        _toText = Bound(1) is { } t ? FilterDates.Format(t, Context.Labels) : "";
    }

    private Task PickDay(DateOnly? day)
    {
        if (day is null) return Task.CompletedTask;
        var value = FilterDateValue.Of(day.Value);
        _text = FilterDates.Format(value, Context.Labels);
        return Context.Commit(value);
    }

    private void ApplyText(int i, string text)
    {
        var parsed = FilterDates.Parse(text, labels: Context.Labels);
        if (parsed is null && text.Trim().Length > 0) return;
        Context.SetValue(i == 0 ? new FilterRange(parsed, Range.To) : new FilterRange(Range.From, parsed));
    }

    private void SetBound(int i, DateOnly? day)
    {
        var value = day is null ? null : FilterDateValue.Of(day.Value);
        if (i == 0) _fromText = value is null ? "" : FilterDates.Format(value, Context.Labels);
        else _toText = value is null ? "" : FilterDates.Format(value, Context.Labels);
        Context.SetValue(i == 0 ? new FilterRange(value, Range.To) : new FilterRange(Range.From, value));
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Escape") { Context.Cancel(); return; }
        if (e.Key != "Enter") return;
        if (IsRange) { await Context.Commit(); return; }
        var parsed = FilterDates.Parse(_text, labels: Context.Labels);
        if (parsed is not null) await Context.Commit(parsed);
    }
}

using System.Globalization;
using System.Text.RegularExpressions;

namespace Lumeo;

/// <summary>A date rule value: a fixed day, or a day relative to today (<c>next week</c>) that
/// resolves when the filter runs.</summary>
public sealed record FilterDateValue(DateOnly? Date = null, FilterRelativeDate? Relative = null, string? Time = null)
{
    public static FilterDateValue Of(DateOnly date, string? time = null) => new(date, null, time);

    /// <summary>The day this value stands for today, or null when it holds nothing.</summary>
    public DateOnly? Resolve(DateOnly? today = null)
    {
        if (Relative is { } r) return r.Apply(today ?? DateOnly.FromDateTime(DateTime.Today));
        return Date;
    }

    public override string ToString() => Relative is { } r ? r.ToString() : Date?.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) ?? "";
}

/// <summary>A day relative to today: <c>Unit</c> days, weeks, months or years ahead (positive) or back.</summary>
public sealed record FilterRelativeDate(FilterDateUnit Unit, int Offset)
{
    public static readonly FilterRelativeDate Today = new(FilterDateUnit.Day, 0);
    public static readonly FilterRelativeDate Tomorrow = new(FilterDateUnit.Day, 1);
    public static readonly FilterRelativeDate Yesterday = new(FilterDateUnit.Day, -1);

    public DateOnly Apply(DateOnly today) => Unit switch
    {
        FilterDateUnit.Day => today.AddDays(Offset),
        FilterDateUnit.Week => today.AddDays(Offset * 7),
        FilterDateUnit.Month => today.AddMonths(Offset),
        _ => today.AddYears(Offset),
    };

    public override string ToString() => $"{(Offset >= 0 ? "+" : "")}{Offset} {Unit.ToString().ToLowerInvariant()}";
}

public enum FilterDateUnit { Day, Week, Month, Year }

/// <summary>Parses and formats date rule values: "today", "next week", "3 days ago", a weekday
/// name, or an explicit date in the current culture. With labels, the phrases the labels produce
/// (<c>heute</c>, <c>in 2 Wochen</c>, <c>vor 3 Tagen</c>) parse as well.</summary>
public static class FilterDates
{
    private static readonly string[] Units = { "day", "week", "month", "year" };

    /// <summary>Parses free text into a date value; null when nothing matches. The English phrases
    /// always work; <paramref name="labels"/> adds the ones the editor shows in its language.</summary>
    public static FilterDateValue? Parse(string text, DateOnly? today = null, CultureInfo? culture = null, FilterLabels? labels = null)
    {
        var now = today ?? DateOnly.FromDateTime(DateTime.Today);
        culture ??= CultureInfo.CurrentCulture;
        var input = Regex.Replace(text.Trim().ToLowerInvariant(), @"\s+", " ");
        if (input.Length == 0) return null;
        if (labels is not null && ParseLocalized(input, labels) is { } localized) return localized;
        if (input is "today" or "now") return new FilterDateValue(Relative: FilterRelativeDate.Today);
        if (input == "tomorrow") return new FilterDateValue(Relative: FilterRelativeDate.Tomorrow);
        if (input == "yesterday") return new FilterDateValue(Relative: FilterRelativeDate.Yesterday);

        var nextLast = Regex.Match(input, @"^(next|last|this) (day|week|month|year)$");
        if (nextLast.Success)
        {
            var direction = nextLast.Groups[1].Value switch { "next" => 1, "last" => -1, _ => 0 };
            return new FilterDateValue(Relative: new FilterRelativeDate(UnitOf(nextLast.Groups[2].Value), direction));
        }

        var counted = Regex.Match(input, @"^(?:in )?(\d+) (day|week|month|year)s?(?: ago)?$");
        if (counted.Success)
        {
            var magnitude = int.Parse(counted.Groups[1].Value, CultureInfo.InvariantCulture);
            var past = input.EndsWith("ago", StringComparison.Ordinal);
            return new FilterDateValue(Relative: new FilterRelativeDate(UnitOf(counted.Groups[2].Value), past ? -magnitude : magnitude));
        }

        var weekday = Regex.Match(input, @"^(?:(next|last|this) )?([a-z]+)$");
        if (weekday.Success)
        {
            var names = culture.DateTimeFormat.DayNames.Select(n => n.ToLowerInvariant()).ToList();
            var english = CultureInfo.InvariantCulture.DateTimeFormat.DayNames.Select(n => n.ToLowerInvariant()).ToList();
            var index = names.IndexOf(weekday.Groups[2].Value);
            if (index < 0) index = english.IndexOf(weekday.Groups[2].Value);
            if (index >= 0)
            {
                var delta = index - (int)now.DayOfWeek;
                if (weekday.Groups[1].Value == "last") { if (delta >= 0) delta -= 7; }
                else if (delta <= 0) delta += 7;
                return new FilterDateValue(Relative: new FilterRelativeDate(FilterDateUnit.Day, delta));
            }
        }

        if (DateOnly.TryParse(text.Trim(), culture, DateTimeStyles.None, out var parsed)
            || DateOnly.TryParseExact(text.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out parsed))
            return FilterDateValue.Of(parsed);
        return null;
    }

    private static FilterDateUnit UnitOf(string word) => (FilterDateUnit)Array.IndexOf(Units, word);

    private static string Normalize(string s) => Regex.Replace(s.Trim().ToLowerInvariant(), @"\s+", " ");

    /// <summary>The phrases <see cref="Format"/> produces from the labels, read back: today,
    /// tomorrow, yesterday, and the "in", "ago" and "this" formats with the labels' unit words.</summary>
    private static FilterDateValue? ParseLocalized(string input, FilterLabels labels)
    {
        if (input == Normalize(labels.DateToday)) return new FilterDateValue(Relative: FilterRelativeDate.Today);
        if (input == Normalize(labels.DateTomorrow)) return new FilterDateValue(Relative: FilterRelativeDate.Tomorrow);
        if (input == Normalize(labels.DateYesterday)) return new FilterDateValue(Relative: FilterRelativeDate.Yesterday);

        var units = new (FilterDateUnit Unit, string Word)[]
            {
                (FilterDateUnit.Day, labels.DateDay), (FilterDateUnit.Day, labels.DateDays),
                (FilterDateUnit.Week, labels.DateWeek), (FilterDateUnit.Week, labels.DateWeeks),
                (FilterDateUnit.Month, labels.DateMonth), (FilterDateUnit.Month, labels.DateMonths),
                (FilterDateUnit.Year, labels.DateYear), (FilterDateUnit.Year, labels.DateYears),
            }
            .Select(u => (u.Unit, Word: Normalize(u.Word)))
            .Where(u => u.Word.Length > 0)
            .OrderByDescending(u => u.Word.Length)
            .ToList();
        if (units.Count == 0) return null;
        var unitPattern = "(?<u>" + string.Join("|", units.Select(u => Regex.Escape(u.Word))) + ")";
        FilterDateUnit? UnitOfWord(string word) => units.Where(u => u.Word == word).Select(u => (FilterDateUnit?)u.Unit).FirstOrDefault();

        string Pattern(string format, bool counted)
        {
            var escaped = Regex.Escape(Normalize(format));
            escaped = counted
                ? escaped.Replace(Regex.Escape("{0}"), @"(?<n>\d+)").Replace(Regex.Escape("{1}"), unitPattern)
                : escaped.Replace(Regex.Escape("{0}"), unitPattern);
            return "^" + escaped + "$";
        }

        foreach (var (format, sign) in new[] { (labels.DateInFormat, 1), (labels.DateAgoFormat, -1) })
        {
            if (string.IsNullOrWhiteSpace(format) || !format.Contains("{0}") || !format.Contains("{1}")) continue;
            var m = Regex.Match(input, Pattern(format, counted: true));
            if (!m.Success || UnitOfWord(m.Groups["u"].Value) is not { } unit) continue;
            if (!int.TryParse(m.Groups["n"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var n)) continue;
            return new FilterDateValue(Relative: new FilterRelativeDate(unit, sign * n));
        }
        if (!string.IsNullOrWhiteSpace(labels.DateThisFormat) && labels.DateThisFormat.Contains("{0}"))
        {
            var m = Regex.Match(input, Pattern(labels.DateThisFormat, counted: false));
            if (m.Success && UnitOfWord(m.Groups["u"].Value) is { } unit)
                return new FilterDateValue(Relative: new FilterRelativeDate(unit, 0));
        }
        return null;
    }

    /// <summary>The value as text: a relative phrase, or the resolved day in the culture's short pattern.</summary>
    public static string Format(FilterDateValue? value, FilterLabels labels, DateOnly? today = null, CultureInfo? culture = null)
    {
        if (value is null) return "";
        culture ??= CultureInfo.CurrentCulture;
        if (value.Relative is { } r)
        {
            if (r.Unit == FilterDateUnit.Day && r.Offset == 0) return labels.DateToday;
            if (r.Unit == FilterDateUnit.Day && r.Offset == 1) return labels.DateTomorrow;
            if (r.Unit == FilterDateUnit.Day && r.Offset == -1) return labels.DateYesterday;
            if (r.Offset > 0) return labels.DateIn(r.Offset, r.Unit);
            if (r.Offset < 0) return labels.DateAgo(-r.Offset, r.Unit);
            return labels.DateThis(r.Unit);
        }
        var resolved = value.Resolve(today);
        if (resolved is null) return "";
        var day = resolved.Value.ToString("d", culture);
        return value.Time is { Length: > 0 } t ? $"{day} {t}" : day;
    }

    /// <summary>Whatever a rule holds for a date field, as a <see cref="FilterDateValue"/>.</summary>
    public static FilterDateValue? Coerce(object? value) => value switch
    {
        null => null,
        FilterDateValue d => d,
        DateOnly d => FilterDateValue.Of(d),
        DateTime dt => FilterDateValue.Of(DateOnly.FromDateTime(dt)),
        DateTimeOffset dto => FilterDateValue.Of(DateOnly.FromDateTime(dto.DateTime)),
        string s => Parse(s),
        _ => null,
    };
}

namespace Lumeo;

/// <summary>What a rule reads as: the operator label (negated or not) and the value text the chip
/// and the advanced row show, resolved through options, dates and the labels.</summary>
public static class FilterDisplay
{
    public static string OperatorLabel(FiltersContext ctx, FilterRule rule, FilterOperatorDef? op)
        => op is not null
            ? (rule.Negated ? string.Format(ctx.Labels.Negated, op.Label) : op.Label)
            : (rule.Operator.Length > 0 ? rule.Operator : ctx.Labels.SelectCondition);

    public static bool IsOptionBacked(FilterField field) => field.Kind is FilterValueKind.Select or FilterValueKind.MultiSelect || field.HasOptions;

    /// <summary>The value segment's text: the field's <see cref="FilterField.ValueText"/>, else a
    /// placeholder for nothing, both bounds of a range, one resolved label, or a count.</summary>
    public static string ValueText(FiltersContext ctx, FilterRule rule, FilterField field, FilterOperatorDef? op)
    {
        if (field.ValueText is not null) return field.ValueText(ValueContext(ctx, rule, field, op));
        var labels = ctx.Labels;
        var value = rule.Value;
        var emptyLabel = IsOptionBacked(field) ? labels.SelectPlaceholder : field.Placeholder ?? labels.ValuePlaceholder;
        if (FilterValues.IsBlank(value)) return emptyLabel;
        if (FilterOperators.ArityOf(op) == FilterArity.Range && value is FilterRange range)
            return string.Format(labels.ValueRange, One(ctx, field, range.From), One(ctx, field, range.To));
        if (value is not string && value is System.Collections.IEnumerable list)
        {
            var items = list.Cast<object?>().ToList();
            if (items.Count == 0) return emptyLabel;
            if (items.Count == 1) return One(ctx, field, items[0]);
            return string.Format(labels.ValueCount, items.Count);
        }
        return One(ctx, field, value);
    }

    /// <summary>The value text with every entry of a many-valued rule spelled out, for a tooltip or a locked bar.</summary>
    public static string FullText(FiltersContext ctx, FilterRule rule, FilterField field, FilterOperatorDef? op)
    {
        var text = ValueText(ctx, rule, field, op);
        var values = rule.Values;
        if (field.ValueText is not null || rule.Value is string || rule.Value is not System.Collections.IEnumerable || FilterOperators.ArityOf(op) == FilterArity.Range || values.Count < 2)
            return text;
        return string.Format(ctx.Labels.ValueDetail, text, string.Join(", ", values.Select(v => One(ctx, field, v))));
    }

    public static string One(FiltersContext ctx, FilterField field, object? value)
    {
        var labels = ctx.Labels;
        switch (value)
        {
            case null: return "";
            case bool b: return b ? labels.True : labels.False;
            case FilterDateValue d: return FilterDates.Format(d, labels);
            case DateOnly d: return FilterDates.Format(FilterDateValue.Of(d), labels);
            case DateTime dt: return FilterDates.Format(FilterDateValue.Of(DateOnly.FromDateTime(dt)), labels);
            default:
                var text = value.ToString() ?? "";
                return ctx.ResolveOption(field, text)?.Label ?? text;
        }
    }

    public static FilterValueContext ValueContext(FiltersContext ctx, FilterRule rule, FilterField field, FilterOperatorDef? op)
    {
        var values = rule.Values;
        var options = values.Select(v => v is null ? null : ctx.ResolveOption(field, v.ToString()!)).Where(o => o is not null).Select(o => o!).ToList();
        return new FilterValueContext(rule.Value, values, field, op ?? new FilterOperatorDef(rule.Operator, rule.Operator), options, ctx.Labels);
    }

    /// <summary>True when a row edits its value in place: a text or number field with a one-valued
    /// operator and no options, custom editor or custom display.</summary>
    public static bool UsesInlineEditor(FiltersContext ctx, FilterField field, FilterOperatorDef? op)
    {
        if (field.Editor is not null || field.EditorTemplate is not null) return false;
        if (field.HasOptions) return false;
        if (field.ValueTemplate is not null || field.ValueText is not null || ctx.ValueTemplate is not null) return false;
        if (field.Kind is not (FilterValueKind.Text or FilterValueKind.Number)) return false;
        return FilterOperators.ArityOf(op) == FilterArity.One;
    }
}

namespace Lumeo;

/// <summary>A rule being built (no <see cref="RuleId"/>) or amended, and the step it is at.</summary>
public sealed record FilterDraft(
    FilterDraftStep Step,
    bool Ready,
    string? RuleId,
    IReadOnlyList<string> Path,
    IReadOnlyList<string> PickerPath,
    string? Operator,
    object? Value,
    string Query)
{
    /// <summary>A fresh draft at the field step.</summary>
    public static FilterDraft Create(IReadOnlyList<string>? pickerPath = null)
        => new(FilterDraftStep.Field, false, null, Array.Empty<string>(), pickerPath ?? Array.Empty<string>(), null, null, "");

    /// <summary>A draft amending an existing rule at a step.</summary>
    public static FilterDraft Amend(FilterRule rule, FilterDraftStep step)
        => new(step, false, rule.Id, rule.Path, rule.Path.Take(Math.Max(0, rule.Path.Count - 1)).ToList(), rule.Operator, rule.Value, "");

    /// <summary>True once a field was chosen.</summary>
    public bool IsCommittable => Path.Count > 0;

    public FilterDraft SelectField(IReadOnlyList<string> path, string? defaultOperator)
        => this with { Path = path, Operator = defaultOperator, Ready = true, Value = null, Step = FilterDraftStep.Operator, Query = "" };

    public FilterDraft SelectOperator(string op, FilterArity arity, object? value)
        => arity == FilterArity.None
            ? this with { Operator = op, Value = null, Ready = true, Query = "" }
            : this with { Operator = op, Value = value, Step = FilterDraftStep.Value, Ready = false, Query = "" };

    public FilterDraft SetValue(object? value) => this with { Value = value };

    public FilterDraft Commit(object? value = null) => this with { Value = value ?? Value, Ready = true };

    public FilterDraft? Back() => Step switch
    {
        FilterDraftStep.Value => this with { Step = FilterDraftStep.Operator, Ready = false, Query = "" },
        FilterDraftStep.Operator => this with { Step = FilterDraftStep.Field, Ready = false, Query = "" },
        _ => null,
    };
}

using Microsoft.AspNetCore.Components;

namespace Lumeo;

/// <summary>What a value editor receives: the rule's field and operator, the draft value, and the
/// actions to commit or leave. Built-in editors and a field's <see cref="FilterField.EditorTemplate"/>
/// render from it.</summary>
public sealed class FilterEditorContext
{
    private readonly Action<object?> _setValue;
    private readonly Func<object?, bool, Task> _commit;
    private readonly Action _cancel;
    private readonly Action _back;

    internal FilterEditorContext(FilterField field, FilterOperatorDef op, object? value, FilterEditorHost host, FilterOptionsState options, FilterLabels labels, Lumeo.Size size, string autoFocusId,
        Action<object?> setValue, Func<object?, bool, Task> commit, Action cancel, Action back)
    {
        Field = field; Operator = op; Value = value; Host = host; Options = options; Labels = labels; Size = size; AutoFocusId = autoFocusId;
        _setValue = setValue; _commit = commit; _cancel = cancel; _back = back;
    }

    public FilterField Field { get; }
    public FilterOperatorDef Operator { get; }
    /// <summary>The draft value; call <see cref="SetValue"/> to change it and <see cref="Commit"/> to store it.</summary>
    public object? Value { get; internal set; }
    public FilterEditorHost Host { get; }
